//! Actual MARKET1 SBF + official Token/ATA processors. Genesis wallets supply
//! only test lamports. Every sold material/Root comes from prior native actions.
#![cfg(not(feature="production-fixture"))]
mod support;
#[path="support/mining.rs"]mod mining;
use support::*;
const PRICE:u64=7_000_000;
fn next(a:&[(Pubkey,Account)],actor:Pubkey)->u64{let n=&account(a,nonce(&actor)).data;if n.is_empty(){0}else{read64(n,120)}}
fn addr(name:&[u8],id:&[u8;32])->Pubkey{Pubkey::find_program_address(&[b"bio",name,id],&PROGRAM).0}
fn listing_id(actor:Pubkey,n:u64)->[u8;32]{let mut op=[0;32];op[..8].copy_from_slice(&n.to_le_bytes());let bk=hash(3,&[&domain(),actor.as_ref(),&op]);hash(26,&[&domain(),&bk])}
fn funds(a:&mut Vec<(Pubkey,Account)>,actor:Pubkey){if !a.iter().any(|(k,_)|*k==actor){a.push((actor,Account{lamports:1_000_000_000,owner:SYSTEM,..Default::default()}));}add_empty(a,nonce(&actor));}
fn text(p:&mut Vec<u8>){p.extend_from_slice(&[14,20]);p.extend_from_slice(b"Living Lines 1");p.extend_from_slice(b"Actual SBF specimen.");}
fn quoted(id:[u8;32],price:u64)->Vec<u8>{let mut p=id.to_vec();p.extend_from_slice(&0u64.to_le_bytes());p.extend_from_slice(&price.to_le_bytes());p.extend_from_slice(&100_000_000u64.to_le_bytes());p}
fn ix(a:&[(Pubkey,Account)],op:u8,actor:Pubkey,p:Vec<u8>,suffix:Vec<AccountMeta>)->Instruction{let mut m=prefix_actor(actor);m.extend(suffix);Instruction{program_id:PROGRAM,accounts:m,data:wire_actor(op,next(a,actor),&p,actor)}}
fn execute(vm:&Mollusk,a:Vec<(Pubkey,Account)>,ix:&Instruction)->Vec<(Pubkey,Account)>{let r=vm.process_instruction(ix,&a);println!("MARKET_NATIVE op{} cu{} raw{:?}",ix.data[8],r.compute_units_consumed,r.raw_result);assert_eq!(r.raw_result,Ok(()));assert_eq!(r.return_data.len(),108);r.resulting_accounts}
fn reject(vm:&Mollusk,a:&[(Pubkey,Account)],ix:&Instruction){let r=vm.process_instruction(ix,a);assert!(r.raw_result.is_err());assert_eq!(r.resulting_accounts,a);}
fn list_material(a:&mut Vec<(Pubkey,Account)>,qty:u64)->(Instruction,[u8;32]){let n=next(a,BOOT);let id=listing_id(BOOT,n);for key in[addr(b"market",&id),addr(b"market-token",&id)]{add_empty(a,key);}let project=project_id(1);let mint=material_address(&project,1,false);let mut p=project.to_vec();p.push(1);for v in[qty,PRICE,100_000_000]{p.extend_from_slice(&v.to_le_bytes());}text(&mut p);(ix(a,41,BOOT,p,vec![AccountMeta::new(addr(b"market",&id),false),AccountMeta::new_readonly(project_address(&project),false),AccountMeta::new_readonly(mint,false),AccountMeta::new(ata(&mint,&BOOT),false),AccountMeta::new(addr(b"market-token",&id),false)]),id)}
fn fill_material(a:&mut Vec<(Pubkey,Account)>,id:[u8;32],buyer:Pubkey)->Instruction{funds(a,buyer);let project=project_id(1);let mint=material_address(&project,1,false);add_empty(a,ata(&mint,&buyer));ix(a,42,buyer,quoted(id,PRICE),vec![AccountMeta::new(addr(b"market",&id),false),AccountMeta::new_readonly(project_address(&project),false),AccountMeta::new_readonly(mint,false),AccountMeta::new(addr(b"market-token",&id),false),AccountMeta::new(ata(&mint,&buyer),false),AccountMeta::new(BOOT,false),AccountMeta::new_readonly(associated_token::ID,false)])}
fn cancel_material(a:&[(Pubkey,Account)],id:[u8;32])->Instruction{let project=project_id(1);let mint=material_address(&project,1,false);ix(a,43,BOOT,quoted(id,PRICE),vec![AccountMeta::new(addr(b"market",&id),false),AccountMeta::new_readonly(project_address(&project),false),AccountMeta::new_readonly(mint,false),AccountMeta::new(addr(b"market-token",&id),false),AccountMeta::new(ata(&mint,&BOOT),false),AccountMeta::new_readonly(associated_token::ID,false)])}
fn list_root(a:&mut Vec<(Pubkey,Account)>,instance:Pubkey,actor:Pubkey)->(Instruction,[u8;32]){let n=next(a,actor);let id=listing_id(actor,n);for key in[addr(b"market",&id),pda(b"mining"),mining::root_reg(instance)]{add_empty(a,key);}let root=account(a,root_address(&instance));let revision=read64(&root.data,354);let rr=&account(a,mining::root_reg(instance)).data;let rr_rev=if rr.is_empty(){0}else{read64(rr,152)};let mut p=instance.to_bytes().to_vec();for v in[revision,rr_rev,PRICE,100_000_000]{p.extend_from_slice(&v.to_le_bytes());}text(&mut p);(ix(a,44,actor,p,vec![AccountMeta::new(addr(b"market",&id),false),AccountMeta::new(pda(b"mining"),false),AccountMeta::new(root_address(&instance),false),AccountMeta::new(mining::root_reg(instance),false)]),id)}
fn fill_root(a:&mut Vec<(Pubkey,Account)>,id:[u8;32],instance:Pubkey,buyer:Pubkey,seller:Pubkey)->Instruction{funds(a,buyer);ix(a,45,buyer,quoted(id,PRICE),vec![AccountMeta::new(addr(b"market",&id),false),AccountMeta::new(root_address(&instance),false),AccountMeta::new_readonly(mining::root_reg(instance),false),AccountMeta::new(seller,false)])}
fn cancel_root(a:&[(Pubkey,Account)],id:[u8;32],instance:Pubkey,seller:Pubkey)->Instruction{ix(a,46,seller,quoted(id,PRICE),vec![AccountMeta::new(addr(b"market",&id),false),AccountMeta::new(root_address(&instance),false)])}
fn transfer_root(a:&[(Pubkey,Account)],instance:Pubkey,actor:Pubkey,to:Pubkey)->Instruction{let root=&account(a,root_address(&instance)).data;let rr=&account(a,mining::root_reg(instance)).data;let mut p=instance.to_bytes().to_vec();p.extend_from_slice(&read64(root,354).to_le_bytes());p.extend_from_slice(&read64(rr,152).to_le_bytes());p.extend_from_slice(to.as_ref());p.extend_from_slice(&100_000_000u64.to_le_bytes());ix(a,26,actor,p,vec![AccountMeta::new(pda(b"mining"),false),AccountMeta::new(root_address(&instance),false),AccountMeta::new(mining::root_reg(instance),false)])}

#[test]
fn actual_material_sale_is_atomic_conserved_and_permanent_with_exact_retry(){
 let vm=runtime();let mut a=stocked(&vm);let mint=material_address(&project_id(1),1,false);let (list,id)=list_material(&mut a,5);a=execute(&vm,a,&list);assert_eq!(read64(&account(&a,ata(&mint,&BOOT)).data,64),25);assert_eq!(read64(&account(&a,addr(b"market-token",&id)).data,64),5);let fill=fill_material(&mut a,id,OTHER);let seller=account(&a,BOOT).lamports;let buyer=account(&a,OTHER).lamports;
 let mut bad=fill.clone();bad.data[128+40]^=1;reject(&vm,&a,&bad);let mut fault=fill.clone();fault.data[0]=0;let rolled=vm.process_transaction_instructions(&[fill.clone(),fault],&a,Some(&OTHER));assert!(rolled.raw_result.is_err());assert_eq!(rolled.resulting_accounts,a);
 let r=vm.process_instruction(&fill,&a);assert_eq!(r.raw_result,Ok(()));assert_eq!(&r.return_data[..8],b"BIOMKR01");assert_eq!(read64(&r.return_data,60),5);std::fs::write(std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../evidence/market1-native-material-record.bin"),&account(&r.resulting_accounts,addr(b"market",&id)).data).unwrap();a=r.resulting_accounts;
 assert_eq!(account(&a,BOOT).lamports,seller+PRICE);let new_rent=account(&a,nonce(&OTHER)).lamports+account(&a,ata(&mint,&OTHER)).lamports;assert_eq!(account(&a,OTHER).lamports,buyer-PRICE-new_rent);assert_eq!(read64(&account(&a,mint).data,36),30);assert_eq!(read64(&account(&a,ata(&mint,&OTHER)).data,64),5);assert_eq!(read64(&account(&a,addr(b"market-token",&id)).data,64),0);assert_eq!(account(&a,addr(b"market",&id)).data[225],1);assert_eq!(read64(&account(&a,pda(b"lab-mint")).data,36),N);
 let retry=vm.process_instruction(&fill,&a);assert_eq!(retry.raw_result,Ok(()));assert_eq!(retry.resulting_accounts,a);let again=fill_material(&mut a,id,OTHER);reject(&vm,&a,&again);reject(&vm,&a,&cancel_material(&a,id));
}
#[test]
fn actual_cancel_recreates_closed_seller_ata_and_cannot_refund_twice(){
 let vm=runtime();let mut a=stocked(&vm);let mint=material_address(&project_id(1),1,false);let (list,id)=list_material(&mut a,30);a=execute(&vm,a,&list);let close=Instruction{program_id:token::ID,accounts:vec![AccountMeta::new(ata(&mint,&BOOT),false),AccountMeta::new(BOOT,false),AccountMeta::new_readonly(BOOT,true)],data:vec![9]};let r=vm.process_instruction(&close,&a);assert_eq!(r.raw_result,Ok(()));a=r.resulting_accounts;assert!(account(&a,ata(&mint,&BOOT)).data.is_empty());let cancel=cancel_material(&a,id);a=execute(&vm,a,&cancel);assert_eq!(read64(&account(&a,ata(&mint,&BOOT)).data,64),30);assert_eq!(read64(&account(&a,mint).data,36),30);assert_eq!(account(&a,addr(b"market",&id)).data[225],2);let retry=vm.process_instruction(&cancel,&a);assert_eq!(retry.raw_result,Ok(()));assert_eq!(retry.resulting_accounts,a);reject(&vm,&a,&cancel_material(&a,id));
}
#[test]
fn unsolicited_escrow_donation_never_blocks_exact_quoted_delivery_or_issues_material(){
 let vm=runtime();let mut a=stocked(&vm);let mint=material_address(&project_id(1),1,false);let (list,id)=list_material(&mut a,5);a=execute(&vm,a,&list);let mut p=vec![3];p.extend_from_slice(&2u64.to_le_bytes());let donate=Instruction{program_id:token::ID,accounts:vec![AccountMeta::new(ata(&mint,&BOOT),false),AccountMeta::new(addr(b"market-token",&id),false),AccountMeta::new_readonly(BOOT,true)],data:p};let r=vm.process_instruction(&donate,&a);assert_eq!(r.raw_result,Ok(()));a=r.resulting_accounts;let fill=fill_material(&mut a,id,OTHER);a=execute(&vm,a,&fill);assert_eq!(read64(&account(&a,ata(&mint,&BOOT)).data,64),23);assert_eq!(read64(&account(&a,ata(&mint,&OTHER)).data,64),5);assert_eq!(read64(&account(&a,addr(b"market-token",&id)).data,64),2);assert_eq!(read64(&account(&a,mint).data,36),30);
}
#[test]
fn genuine_root_sale_keeps_capsule_identity_and_blocks_owner_transfer_or_duplicate_sale(){
 let vm=runtime();let (mut a,instance)=manufactured(&vm);let original=account(&a,root_address(&instance)).data.clone();let (list,id)=list_root(&mut a,instance,BOOT);a=execute(&vm,a,&list);let held=&account(&a,root_address(&instance)).data;assert_eq!(&held[322..354],addr(b"market",&id).as_ref());assert_eq!(read64(held,354),1);assert_eq!(&held[..322],&original[..322]);assert_eq!(&held[443..],&original[443..]);reject(&vm,&a,&transfer_root(&a,instance,BOOT,OTHER));let (double,_)=list_root(&mut a,instance,BOOT);reject(&vm,&a,&double);let fill=fill_root(&mut a,id,instance,OTHER,BOOT);let seller=account(&a,BOOT).lamports;let mut fault=fill.clone();fault.data[0]=0;let r=vm.process_transaction_instructions(&[fill.clone(),fault],&a,Some(&OTHER));assert!(r.raw_result.is_err());assert_eq!(r.resulting_accounts,a);a=execute(&vm,a,&fill);let sold=&account(&a,root_address(&instance)).data;assert_eq!(&sold[322..354],OTHER.as_ref());assert_eq!(read64(sold,354),2);assert_eq!(account(&a,BOOT).lamports,seller+PRICE);assert_eq!(&sold[..322],&original[..322]);assert_eq!(&sold[443..],&original[443..]);let retry=vm.process_instruction(&fill,&a);assert_eq!(retry.raw_result,Ok(()));assert_eq!(retry.resulting_accounts,a);let again=fill_root(&mut a,id,instance,OTHER,BOOT);reject(&vm,&a,&again);reject(&vm,&a,&cancel_root(&a,id,instance,BOOT));
 let a=mining::stake(&vm,a,instance,OTHER,OTHER);let mut attempt=a.clone();let (list,_)=list_root(&mut attempt,instance,OTHER);reject(&vm,&attempt,&list);assert_eq!(read64(&account(&a,pda(b"lab-mint")).data,36),N);
}
#[test]
fn genuine_root_cancel_only_restores_original_seller_and_stale_quotes_have_no_effect(){
 let vm=runtime();let (mut a,instance)=manufactured(&vm);let (list,id)=list_root(&mut a,instance,BOOT);a=execute(&vm,a,&list);funds(&mut a,OTHER);let wrong=cancel_root(&a,id,instance,OTHER);reject(&vm,&a,&wrong);let cancel=cancel_root(&a,id,instance,BOOT);a=execute(&vm,a,&cancel);assert_eq!(&account(&a,root_address(&instance)).data[322..354],BOOT.as_ref());assert_eq!(read64(&account(&a,root_address(&instance)).data,354),2);assert_eq!(account(&a,addr(b"market",&id)).data[225],2);reject(&vm,&a,&cancel_root(&a,id,instance,BOOT));let fill=fill_root(&mut a,id,instance,OTHER,BOOT);reject(&vm,&a,&fill);
}

fn stake_attempt(a:&mut Vec<(Pubkey,Account)>,instance:Pubkey,actor:Pubkey)->Instruction{
 for key in[mining::directory(0),mining::position(instance,0),mining::hour(0),mining::event_key(0)]{add_empty(a,key);}let mut p=instance.to_bytes().to_vec();p.extend_from_slice(&read64(&account(a,root_address(&instance)).data,354).to_le_bytes());p.extend_from_slice(&0u64.to_le_bytes());p.extend_from_slice(&0u64.to_le_bytes());p.extend_from_slice(actor.as_ref());p.extend_from_slice(&100_000_000u64.to_le_bytes());ix(a,20,actor,p,vec![AccountMeta::new_readonly(pda(b"lab-mint"),false),AccountMeta::new_readonly(pda(b"lab-reserve"),false),AccountMeta::new_readonly(pda(b"lab-auth"),false),AccountMeta::new(pda(b"treasury"),false),AccountMeta::new(pda(b"mining"),false),AccountMeta::new_readonly(root_address(&instance),false),AccountMeta::new(mining::root_reg(instance),false),AccountMeta::new(mining::directory(0),false),AccountMeta::new(mining::position(instance,0),false),AccountMeta::new(mining::hour(0),false),AccountMeta::new(mining::event_key(0),false)])
}
#[test]
fn material_class_text_and_rent_cap_are_real_native_gates(){let vm=runtime();let mut a=stocked(&vm);let (valid,_)=list_material(&mut a,5);for at in[128+32,128+57]{let mut bad=valid.clone();bad.data[at]^=1;reject(&vm,&a,&bad);}let mut capped=valid.clone();capped.data[128+49..128+57].fill(0);reject(&vm,&a,&capped);let mut control=valid.clone();control.data[128+59]=0;reject(&vm,&a,&control);}
#[test]
fn listed_root_cannot_stake_or_be_misclassified_as_a_biological_parent(){let vm=runtime();let (mut a,instance)=manufactured(&vm);let(list,id)=list_root(&mut a,instance,BOOT);a=execute(&vm,a,&list);let attempt=stake_attempt(&mut a,instance,BOOT);reject(&vm,&a,&attempt);let fill=fill_root(&mut a,id,instance,OTHER,BOOT);let mut forged=a.clone();let body=&mut account_mut(&mut forged,addr(b"market",&id)).data[120..];body[106]=3;body[108]=4;body[109]=22;reject(&vm,&forged,&fill);}
#[test]
fn real_old_unclaimed_position_is_unchanged_by_sale_and_still_pays_original_beneficiary(){
 let mut vm=runtime();let (mut a,instance)=manufactured(&vm);let start=mining::local_start(&a);clock_at(&mut vm,&mut a,start+1);a=mining::create_lab_ata(&vm,a,BOOT);a=mining::stake(&vm,a,instance,BOOT,BOOT);let mut pending=a.clone();let(blocked,_)=list_root(&mut pending,instance,BOOT);reject(&vm,&pending,&blocked);clock_at(&mut vm,&mut a,start+7201);a=mining::exit(&vm,a,instance,BOOT);let mut before_boundary=a.clone();let (early,_)=list_root(&mut before_boundary,instance,BOOT);reject(&vm,&before_boundary,&early);clock_at(&mut vm,&mut a,start+10801);let mut uncovered=a.clone();let (early,_)=list_root(&mut uncovered,instance,BOOT);reject(&vm,&uncovered,&early);a=mining::settle_through(&vm,a,3);let pos=mining::position(instance,0);let old=account(&a,pos).data.clone();let earned=read64(&old,351);assert!(earned>0);assert_eq!(read64(&old,359),0);let (list,id)=list_root(&mut a,instance,BOOT);a=execute(&vm,a,&list);let fill=fill_root(&mut a,id,instance,OTHER,BOOT);a=execute(&vm,a,&fill);assert_eq!(account(&a,pos).data,old);let before=read64(&account(&a,ata(&pda(b"lab-mint"),&BOOT)).data,64);a=mining::claim(&vm,a,instance,0,OTHER);assert_eq!(&account(&a,pos).data[200..232],BOOT.as_ref());assert_eq!(read64(&account(&a,pos).data,359),earned);assert_eq!(read64(&account(&a,ata(&pda(b"lab-mint"),&BOOT)).data,64),before+earned);
}
